  void EditSelectedStageDuration(){var p=Selected();int index=subtasks.SelectedIndex;if(engine.State!=Phase.Idle||p==null||index<0||index>=p.Stages.Count)return;var stage=p.Stages[index];using(var f=new Form()){UI.FormStyle(f,"修改子任务时长",470,260);f.Padding=new Padding(20);decimal initial=(decimal)Math.Max(0.1,TaskSupport.StageSeconds(p,stage,data)/60.0);var value=new NumericUpDown{Minimum=.1M,Maximum=Math.Max(1,p.Challenge?p.ChallengeMinutes:(p.PomodoroMinutes>0?p.PomodoroMinutes:data.FocusMinutes)),DecimalPlaces=1,Increment=.5M,Value=Math.Min(initial,Math.Max(1,p.Challenge?p.ChallengeMinutes:(p.PomodoroMinutes>0?p.PomodoroMinutes:data.FocusMinutes))),Width=100,Margin=new Padding(8)};var root=UI.Table(1,48,62,58);root.Controls.Add(UI.Label(stage.Title,12,true),0,0);root.Controls.Add(UI.Flow(UI.Label("分配时长（分钟）",10),value),0,1);root.Controls.Add(UI.Flow(UI.Button("保存",()=>{int total=Math.Max(60,(p.Challenge?p.ChallengeMinutes:(p.PomodoroMinutes>0?p.PomodoroMinutes:data.FocusMinutes))*60),seconds=Math.Max(1,(int)Math.Round((double)value.Value*60)),share=Math.Max(1,(int)Math.Round(seconds*100.0/total));stage.AllocatedSeconds=seconds;if(index+1<p.Stages.Count){int after=index+2<p.Stages.Count?p.Stages[index+2].Remaining:0;p.Stages[index+1].Remaining=Math.Max(after,Math.Min(stage.Remaining,stage.Remaining-share));p.Stages[index+1].AllocatedSeconds=0;}else{int upper=index==0?100:p.Stages[index-1].Remaining;stage.Remaining=Math.Max(0,Math.Min(upper,share));}p.UpdatedUtc=DateTime.UtcNow;Save();RefreshSubtasks();RefreshDisplay();f.Close();},true),UI.Button("取消",()=>f.Close())),0,2);f.Controls.Add(root);f.ShowDialog(this);}}
  void EditResume(){EditResumeFor(DisplayProject());}
  void EditResumeFor(Project p){if(p==null||p.Completed)return;using(var d=new ResumeDialog(p,api,data)){if(d.ShowDialog(this)==DialogResult.OK){undoProject=null;Save();Feedback("接续卡已保存，下次可以从这里继续。");RefreshDisplay();}}}
  void Unstuck(){var p=DisplayProject();if(p==null||p.Completed)return;using(var d=new StuckDialog(p)){if(d.ShowDialog(this)==DialogResult.OK){undoProject=null;p.SmallStep=d.Result;p.UpdatedUtc=DateTime.UtcNow;Save();Feedback("起步动作已缩小，计时规则没有改变。");RefreshDisplay();}}}
  void FinishStep(){var p=DisplayProject();if(engine.Current==p)HandleEvent(engine.Tick(DateTime.UtcNow));if(p==null||p.Completed)return;var stage=p.Stages.FirstOrDefault(x=>!x.Done);if(String.IsNullOrWhiteSpace(p.SmallStep)&&stage==null)return;undoProject=p;undoSmall=p.SmallStep;undoStage=String.IsNullOrWhiteSpace(p.SmallStep)?stage:null;string done=TaskSupport.Next(p);if(undoStage!=null)undoStage.Done=true;else p.SmallStep="";if(engine.Current==p)engine.RefreshStageDeadline();p.LastCheckpoint="刚刚做完："+done;p.UpdatedUtc=DateTime.UtcNow;Feedback("这一步已记录，可以继续，也可以先停下。");Save();RefreshSubtasks();RefreshDisplay();}
  void UndoStep(){if(undoProject==null||undoProject!=DisplayProject()||undoProject.Completed)return;if(undoStage!=null){if(!undoProject.Stages.Contains(undoStage))return;undoStage.Done=false;}else undoProject.SmallStep=undoSmall;if(engine.Current==undoProject)engine.RefreshStageDeadline();undoProject.LastCheckpoint="已恢复上一步";undoProject.UpdatedUtc=DateTime.UtcNow;undoProject=null;Save();RefreshSubtasks();Feedback("上一步已恢复。");RefreshDisplay();}
  void WithdrawLastStage(){var p=DisplayProject();if(p==null||p.Completed)return;var stage=p.Stages.LastOrDefault(x=>x.Done);if(stage==null)return;stage.Done=false;if(engine.Current==p)engine.RefreshStageDeadline();p.UpdatedUtc=DateTime.UtcNow;Feedback("已撤回完成标记，可以重新推进这一步。");Save();RefreshSubtasks();RefreshDisplay();}
  Project Selected(){return projects.SelectedIndex>=0&&projects.SelectedIndex<visibleProjects.Count?visibleProjects[projects.SelectedIndex]:null;}
  Project DisplayProject(){return engine.State!=Phase.Idle?engine.Current:Selected();}
  void RefreshProjects(string selectedId){updating=true;projects.Items.Clear();visibleProjects=data.Projects.Where(p=>!p.Deleted&&p.Completed==completedView.Checked).ToList();int projectExtent=0;foreach(var p in visibleProjects){string label=(p.Stages!=null&&p.Stages.Count>0?"▸ ":"")+p.Name;projects.Items.Add(label);projectExtent=Math.Max(projectExtent,TextRenderer.MeasureText(label,projects.Font).Width+36);}projects.HorizontalScrollbar=true;projects.HorizontalExtent=Math.Max(0,projectExtent);int index=visibleProjects.FindIndex(p=>p.Id==selectedId);if(index>=0)projects.SelectedIndex=index;else if(projects.Items.Count>0)projects.SelectedIndex=0;updating=false;stepsExpanded=projects.SelectedIndex>=0;RefreshSubtasks();RefreshDisplay();}
  void RefreshSubtasks(){updating=true;shownProject=DisplayProject();subtasks.Items.Clear();int extent=0;if(shownProject!=null)foreach(var s in shownProject.Stages){string label=s.Title+"  ·  "+FocusEngine.Duration(TaskSupport.StageSeconds(shownProject,s,data));subtasks.Items.Add(label,s.Done);extent=Math.Max(extent,TextRenderer.MeasureText(label,subtasks.Font).Width+34);}subtasks.HorizontalExtent=Math.Max(0,extent);updating=false;}
  void EditProject(Project project){if(project!=null&&engine.State!=Phase.Idle&&engine.Current!=null&&project.Id==engine.Current.Id){MessageBox.Show(this,"请先结束当前任务，再修改模式或子任务计划。子任务仍可以直接勾选。","先结束计时");return;}using(var d=new ProjectDialog(project??new Project(),api,store.DirectoryPath,data)){if(d.ShowDialog(this)!=DialogResult.OK)return;int i=data.Projects.FindIndex(p=>p.Id==d.Result.Id);if(i<0)data.Projects.Add(d.Result);else data.Projects[i]=d.Result;Save();RefreshProjects(d.Result.Id);RefreshHistory();}}
  void DeleteSelected(){var p=Selected();if(p==null)return;if(engine.State!=Phase.Idle&&engine.Current==p){MessageBox.Show(this,"请先结束本次计时，再删除任务。删除将一并清除该项目的历史记录。");return;}p.Deleted=true;p.UpdatedUtc=DateTime.UtcNow;data.Records.RemoveAll(r=>r.ProjectId==p.Id);data.ChallengeAdjustments.RemoveAll(a=>a.ProjectId==p.Id);data.FreshContents.RemoveAll(a=>a.ProjectId==p.Id);data.DistractionLog.RemoveAll(a=>a.ProjectId==p.Id);undoProject=null;Save();RefreshProjects(null);RefreshHistory();}
  void CopySelected(){var p=Selected();if(p==null)return;if(engine.State!=Phase.Idle&&engine.Current==p){MessageBox.Show(this,"请先结束本次计时，再复制该任务。","先结束计时");return;}var copy=new Project{Name=UniqueProjectName(p.Name),NextStep=p.NextStep,SmallStep="",ResumeNote="",DoneWhen=p.DoneWhen,Challenge=p.Challenge,ChallengeMinutes=p.ChallengeMinutes,ChallengeMinutesCustomized=p.ChallengeMinutesCustomized,PomodoroMinutes=p.PomodoroMinutes,AllowDistraction=p.AllowDistraction,PlanSource=p.PlanSource};foreach(var s in p.Stages)copy.Stages.Add(new Stage{Title=s.Title,Action=s.Action,Remaining=s.Remaining,AllocatedSeconds=s.AllocatedSeconds,Done=false});copy.UpdatedUtc=DateTime.UtcNow;data.Projects.Add(copy);Save();RefreshProjects(copy.Id);RefreshHistory();Feedback("已复制为“"+copy.Name+"”，子任务的完成状态已清零。");}
  string UniqueProjectName(string baseName){string name=String.IsNullOrWhiteSpace(baseName)?"未命名任务":baseName.Trim();int n=1;int open=name.LastIndexOf('（');if(open>0&&name.EndsWith("）")){int value;if(Int32.TryParse(name.Substring(open+1,name.Length-open-2),out value)&&value>0){name=name.Substring(0,open).TrimEnd();n=value+1;}}var taken=new HashSet<string>(data.Projects.Where(x=>!x.Deleted).Select(x=>x.Name));string candidate=name+"（"+n+"）";while(taken.Contains(candidate)){n++;candidate=name+"（"+n+"）";}return candidate;}
