  void HandleEvent(string evt){
   if(evt==null)return;Save();
   if(evt=="due"){ShowNotice("到休息时间了","项目："+engine.Current.Name+"\n已专注 "+FocusEngine.Duration(engine.RunSeconds)+"\n\n计时已暂停。点击开始休息才开始休息倒计时；关闭弹窗仍保持暂停。","due",Pair("开始休息",()=>BeginBreak()),Pair("继续专注 5 分钟",()=>PauseResume()),Pair("结束本次",()=>EndFocus("手动结束")));QueueBreakEncouragement(notice);}
   else if(evt=="challenge-break")ShowNotice("休息提醒","已经连续专注 "+data.FocusMinutes+" 分钟。挑战计时已暂停，可以现在休息，也可以继续挑战。","challenge-break",Pair("开始休息",()=>BeginBreak()),Pair("继续挑战",()=>{engine.SkipChallengeBreak(DateTime.UtcNow);CloseNotice();Save();RefreshDisplay();}),Pair("保持暂停",null));
   else if(evt=="stage")ShowChallengeStage();
   else if(evt=="challenge-end")ShowChallengeDeadline();
   else if(evt=="break-end")ShowNotice("休息结束，准备回来了吗？","休息已结束，当前没有累计专注时间。\n\n点击继续才会开始新一轮，也可以先结束这个任务。","break-end",Pair("继续此任务",()=>StartSelected()),Pair("结束本次",()=>EndFocus("休息后结束")));
   else if(evt=="interrupted")ShowNotice("已暂停，避免误计时间","检测到系统睡眠或较长中断，未把这段空档记为专注。\n\n你回来后点击继续即可。","interrupted",Pair("继续计时",()=>PauseResume()),Pair("先保持暂停",null));
  }
