  static MemoryStream ToneWave(int[] notes){const int rate=44100;int toneSamples=rate*110/1000,gapSamples=rate*35/1000,total=notes.Length*toneSamples+Math.Max(0,notes.Length-1)*gapSamples;var stream=new MemoryStream();using(var w=new BinaryWriter(stream,Encoding.ASCII,true)){w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+total*2);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(total*2);for(int n=0;n<notes.Length;n++){for(int i=0;i<toneSamples;i++){double envelope=Math.Min(1,Math.Min(i/(rate*.012),(toneSamples-i)/(rate*.025)));short sample=(short)(Math.Sin(2*Math.PI*notes[n]*i/rate)*9000*envelope);w.Write(sample);}if(n<notes.Length-1)for(int i=0;i<gapSamples;i++)w.Write((short)0);}}stream.Position=0;return stream;}
