   if(syncing)return;nextSync=DateTime.UtcNow.AddMinutes(5);if(engine.State!=Phase.Idle){if(!automatic)MessageBox.Show(this,"请先结束当前计时，再同步。自动同步会在空闲时进行。");return;}if(String.IsNullOrWhiteSpace(sync.Url)){if(!automatic)MessageBox.Show(this,"请先打开“同步设置”，填写 WebDAV 地址和账号。");return;}if(!Save())return;
   syncing=true;syncStatus.Text="正在同步：先下载并合并，再安全上传……";syncCancel=new CancellationTokenSource();
   try{var merged=await WebDavSync.Run(sync,()=>Store.Decode(Store.Encode(data)),syncCancel.Token);if(IsDisposed||closing)return;PreMergeBackup();ApplyMerged(DataMerge.Merge(data,merged));syncStatus.Text="同步完成 "+DateTime.Now.ToString("HH:mm:ss")+" · 重复记录已去重，断网仍可使用。";}
   catch(OperationCanceledException){if(!IsDisposed)syncStatus.Text="同步取消或超时，本地记录保留。";}
   catch(Exception ex){if(!IsDisposed)syncStatus.Text=ex is InvalidOperationException?ex.Message:"同步失败，请检查网络、凭据和远端数据格式；本地数据保留。";}
   finally{syncing=false;if(syncCancel!=null){syncCancel.Dispose();syncCancel=null;}}
  }
  bool Save(){try{store.Save(data);savedAt=DateTime.UtcNow;saveError=false;status.Text="本地已保存 "+DateTime.Now.ToString("HH:mm:ss")+" · 最小化进托盘；关闭窗口退出";status.ForeColor=UI.Muted;return true;}catch(Exception){savedAt=DateTime.UtcNow;status.Text="保存失败：数据目录不可写或磁盘空间不足。请勿关闭程序。";status.ForeColor=Color.Firebrick;if(!saveError){saveError=true;ShowNotice("数据暂时无法保存","请检查数据目录和磁盘空间。当前计时仍在内存中，请暂时不要关闭程序。","save-error",Pair("知道了",null));}return false;}}
  void OpenFolder(){try{Directory.CreateDirectory(store.DirectoryPath);Process.Start(new ProcessStartInfo("explorer.exe","\""+store.DirectoryPath+"\""){UseShellExecute=true});}catch(Exception){MessageBox.Show(this,store.DirectoryPath,"数据目录");}}
  void BuildTray(){tray=new NotifyIcon{Icon=Icon,Text=Brand.AppName+" · 种下一点进展",Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("打开专注小站",null,(s,e)=>ShowMain());menu.Items.Add("迷你计时条",null,(s,e)=>ShowMini());menu.Items.Add("暂停 / 继续",null,(s,e)=>PauseResume());menu.Items.Add("结束本次计时",null,(s,e)=>EndFocus("手动结束"));menu.Items.Add("完成当前任务",null,(s,e)=>CompleteTask());menu.Items.Add("退出程序",null,(s,e)=>{exitRequested=true;Close();});tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,e)=>ShowMain();}
  void FinishMiniStep(){var p=DisplayProject();if(p==null)return;var stage=p.Stages.FirstOrDefault(x=>!x.Done);if(stage==null)return;if(engine.IsChallenge&&engine.Current==p){double saved=engine.PlannedStageRemaining(stage);engine.Pause(DateTime.UtcNow);stage.Done=true;p.SmallStep="";p.UpdatedUtc=DateTime.UtcNow;Save();RefreshSubtasks();RefreshDisplay();ChallengeEarly(stage,saved);return;}HandleEvent(engine.Tick(DateTime.UtcNow));undoProject=p;undoStage=stage;undoSmall=p.SmallStep;p.SmallStep="";stage.Done=true;if(engine.Current==p)engine.RefreshStageDeadline();p.UpdatedUtc=DateTime.UtcNow;Save();RefreshSubtasks();RefreshDisplay();} void ShowMini(){if(mini==null||mini.IsDisposed)mini=new MiniTimer(()=>{if(engine.State==Phase.Idle||engine.State==Phase.Ready)StartSelected();else if(engine.State==Phase.Break)EarlyFocus();else PauseResume();},()=>ShowMain(),()=>EndFocus("手动结束"),()=>CompleteTask(),()=>BeginBreak(),()=>FinishMiniStep(),()=>ShowDistraction(),()=>WithdrawLastStage(),()=>NextRestLine());if(mini.WindowState==FormWindowState.Minimized)mini.WindowState=FormWindowState.Normal;mini.Show();var miniArea=Screen.FromControl(mini).WorkingArea;mini.Location=new Point(Math.Max(miniArea.Left,Math.Min(mini.Left,miniArea.Right-mini.Width)),Math.Max(miniArea.Top,Math.Min(mini.Top,miniArea.Bottom-mini.Height)));mini.Activate();RefreshDisplay();Hide();}
  public void ShowMain(){Show();WindowState=FormWindowState.Normal;Activate();if(mini!=null&&!mini.IsDisposed)mini.Show();}
  void PowerChanged(object sender,PowerModeChangedEventArgs e){if(e.Mode==PowerModes.Suspend&&IsHandleCreated&&!IsDisposed){try{Invoke(new Action(()=>{if(engine.State==Phase.Focus){engine.Pause(DateTime.UtcNow);Save();RefreshDisplay();}}));}catch(InvalidOperationException){}}}
  void SessionChanged(object sender,SessionSwitchEventArgs e){if(e.Reason==SessionSwitchReason.SessionLock&&IsHandleCreated&&!IsDisposed){try{BeginInvoke(new Action(()=>{if(engine.State==Phase.Focus){engine.Pause(DateTime.UtcNow);Save();RefreshDisplay();}}));}catch(InvalidOperationException){}}}
  void OnClosing(object sender,FormClosingEventArgs e){if(closing)return;if(e.CloseReason==CloseReason.UserClosing&&data.CloseToTray&&!exitRequested){e.Cancel=true;Hide();status.Text="已收进托盘；计时和提醒继续运行。";return;}if(distractionCancel!=null)distractionCancel.Cancel();if(engine.State!=Phase.Idle)TaskSupport.Remember(engine.Current);bool focused=engine.State==Phase.Focus||engine.State==Phase.Paused;if(engine.State!=Phase.Idle)engine.Stop(DateTime.UtcNow,"退出程序");if(!Save()){e.Cancel=true;return;}closing=true;if(breakCancel!=null)breakCancel.Cancel();timer.Stop();CloseNotice();if(mini!=null&&!mini.IsDisposed)mini.Close();if(syncCancel!=null)syncCancel.Cancel();if(focused&&e.CloseReason==CloseReason.UserClosing){using(var n=new Notice("专注结束，记录已保存",(engine.Current==null?"":engine.Current.Name)+"\n本轮 "+FocusEngine.Duration(engine.RunSeconds)+"\n\n程序退出后不再计时。",Pair("退出程序",null)))n.ShowDialog();}SystemEvents.PowerModeChanged-=PowerChanged;SystemEvents.SessionSwitch-=SessionChanged;tray.Visible=false;tray.Dispose();timer.Dispose();}
  [DllImport("user32.dll",CharSet=CharSet.Auto)]static extern bool DestroyIcon(IntPtr handle);
  static Icon SeedIcon(){using(var image=new Bitmap(32,32))using(var g=Graphics.FromImage(image)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var stem=new Pen(Color.FromArgb(53,89,65),3)){g.DrawCurve(stem,new[]{new Point(16,28),new Point(15,21),new Point(17,14)});}using(var leaf=new SolidBrush(Color.FromArgb(91,132,73))){g.FillEllipse(leaf,new Rectangle(7,10,11,8));g.FillEllipse(leaf,new Rectangle(16,6,10,9));}using(var seed=new SolidBrush(Color.FromArgb(174,122,62)))g.FillEllipse(seed,new Rectangle(12,20,8,9));IntPtr h=image.GetHicon();try{using(var icon=Icon.FromHandle(h))return (Icon)icon.Clone();}finally{DestroyIcon(h);}}}
 }
